import json
import os
I=json.load(open(os.environ.get('PF_IMG','/tmp/nat/cs/img.json')))
def X(k,alt,cap='',cls=''): return fig(k,alt,cap,cls) if k in I else ''
def img(k,alt): return f'<img src="{I[k]}" alt="{alt}" loading="lazy">'
def fig(k,alt,cap='',cls=''): return f'<figure class="cs-fig cs-rv {cls}"><div class="fr">{img(k,alt)}</div>'+(f'<figcaption>{cap}</figcaption>' if cap else '')+'</figure>'
def quotes(items,title): return f'<p class="cs-mini cs-rv">{title}</p><ul class="cs-q">'+''.join(f'<li class="cs-rv" style="--d:{i*70}ms">“{q}”</li>' for i,q in enumerate(items))+'</ul>'
def ins(items,title): return f'<p class="cs-mini cs-rv">{title}</p><ul class="cs-ins">'+''.join(f'<li class="cs-rv" style="--d:{i*70}ms">{q}</li>' for i,q in enumerate(items))+'</ul>'
def step(label,text,*extra): return f'<div class="cs-step"><h3 class="cs-rv">{label}</h3><p class="cs-rv">{text}</p>'+''.join(extra)+'</div>'
def phase(n,name,sid): return f'<header class="cs-phh cs-rv" data-sec="{sid}"><b>{n}</b><h2>{name}</h2></header>'
def two(eye,h,body,sid=''): return f'<div class="cs-two"'+(f' data-sec="{sid}"' if sid else '')+f'><div class="cs-rv"><p class="cs-eye">{eye}</p><h2 class="cs-h2">{h}</h2></div><div class="cs-rv" style="--d:90ms">{body}</div></div>'
def prob(t): return f'<figure class="cs-prob cs-rv"><p class="cs-eye">Problem statement</p><blockquote>{t}</blockquote></figure>'
def rail(items): return '<nav class="cs-rail" aria-label="Case study sections"><div class="in">'+''.join(f'<button type="button" data-to="{s}">{n}</button>' for n,s in items)+'</div><i class="bar"></i></nav>'
def meta(items): return '<dl class="cs-meta">'+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in items)+'</dl>'
def nxt(go,name): return f'<a class="cs-next" data-go="{go}"><div><span class="cs-eye">Next case study</span><div class="ttl">{name}</div></div><span class="ar" aria-hidden="true">→</span></a>'
MED='<a class="cs-btn" href="https://medium.com/@freddie.grzybowski" target="_blank" rel="noopener">Read the full case study on Medium <span aria-hidden="true">↗</span></a>'

phones=''.join(f'<div class="cs-dv" style="--i:{i}">{img(k,"EVA app screen")}</div>' for i,k in enumerate(['hero2','hero3','hero1','hero4','hero5']))
ALTA_FX='<div class="cs-fx" aria-hidden="true"><svg class="cs-line" viewBox="0 0 1200 300" preserveAspectRatio="none"><path d="M0 220 C120 220 150 120 260 130 S420 240 520 180 S700 60 800 110 S980 210 1060 120 S1160 60 1200 80"/><g><circle cx="260" cy="130" r="7"/><circle cx="520" cy="180" r="7"/><circle cx="800" cy="110" r="7"/><circle cx="1060" cy="120" r="7"/></g></svg></div>'
BAL_FX='<div class="cs-fx" aria-hidden="true"><i class="cs-br q1"></i><i class="cs-br q2"></i><i class="cs-br q3"></i></div>'

alta=f'''<div class="pg cs" data-pg="alta">
<section class="cs-hero">{ALTA_FX}<p class="cs-eye">Client project · Healthtech · 3 week sprint</p><h1 class="cs-h1">Alta Flora</h1><p class="cs-intro">A three week design sprint for Alta Flora’s medical tracking app EVA. In this project I worked in a team of four UX Designers, myself, Scarlet Eadie, Jamie Curtis and Helena Saez.</p>{meta([('Role','UX Designer'),('Team','4 UX designers'),('Duration','3 weeks'),('Focus','Onboarding · Tracking · Data')])}<div class="cs-phones five">{phones}</div></section>
<div class="cs-sheet">{rail([('Overview','overview'),('Discover','discover'),('Explore','explore'),('Develop','develop'),('Deliver','deliver'),('Learnings','learnings')])}
<div class="cs-wrap">
{two('The client','Who are Alta Flora?','<p class="cs-lead">Alta Flora built an app (EVA) for patients consuming legal prescription medical cannabis in the UK in 2019 and released it into the app store in Nov 2020. Now they have expanded to all types of medication, not just cannabis based. EVA is a free app, helping you track your medication and symptoms in order to aid communication with your doctor and improve quality of life.</p>','overview')}
{two('The brief','Brief','<p class="cs-lead">We were approached by Alta flora who wanted their users to find a way to effectively and intuitively track how medical cannabis and other medications impact their symptoms and how this would improve their quality of life. Their main objectives were as follow:</p><ol class="cs-obj"><li><b>01</b><span>To explore the onboarding journey and help communicate how to best use the app and what are the benefits of tracking.</span></li><li><b>02</b><span>Understand what kind of information users are interested in tracking as well as how best to visualise this data.</span></li><li><b>03</b><span>To review the current app and its features.</span></li></ol>')}
{two('What we delivered','Deliverables','<ul class="cs-del"><li>Research insight &amp; findings concerning competitors, user types, and behaviour</li><li>Personas and scenarios</li><li>Experience map / user journeys</li><li>Information architecture</li><li>Design &amp; usability recommendations for improvement</li><li>User flows and screen flows</li><li>Product sketches and wireframes</li><li>High fidelity mock-up</li><li>Prototype of design(s)</li><li>A final presentation to the client which summarises the UX work</li></ul>')}
<section class="cs-phase" style="--k:0">{phase('01','Discover','discover')}
{step('Competitive / Comparative Analysis','Conducted in-depth research - to check other medical tracking apps, through this we learned that most apps are overwhelming and often not relevant to the users medical condition.',fig('comp','Competitive research boards','Competitive research of other apps like Flo and Migraine Buddy','sm'))}
{step('Usability Testing','We decided diary studies would be a good way to see how users find interacting with EVA over a few days—and how data was visually fed back to them during this time. This was conducted with three users over a period of four days. Along with the diary studies we also went ahead with usability tests to see first hand how the users interact with the app currently. We did this with four users.',quotes(['needs to hold your hand a lot more','what is the difference between Discover and Explore','when I logged my symptoms and clicked save it just went back to 0 with no confirmation so that was a big issue','I would like to be able to get reminders/notifications about specific meds'],'Insights from the initial test'))}
</section>
<section class="cs-phase" style="--k:1">{phase('02','Explore','explore')}
{step('Interviews','After deliberating with the team as to how to approach this and what questions to ask, we set up a survey as a way to gather information on tracking in general and filter through these to get our interviewees. We managed to get 9 interviews (7 people who monitor a health-related issue and 2 doctors) part-selected by our survey.',X('interviews','Interview research for Alta Flora','','sm'))}
{step('Persona','We gathered all our notes from the interviews and synthesised them in an affinity map, which very quickly led us to see trends that we incorporated in our primary persona Pia:',fig('pia','Persona Pia','Pia: behaviours, frustrations, needs and goals'),ins(['Clear onboarding is needed to help Pia when using an app','A lack in motivation as feedback takes time to develop','Personalisation is important so she gets information related to her','A way to spot patterns and triggers','To have access to her data in a clear format whenever she needs it'],'Our insights'))}
{prob('“Pia needs an accessible, efficient and organised way to monitor her condition and new medication on one platform, including her symptoms, side effects and triggers, in order to predict and manage her health and wellbeing”')}
{step('User Journey','We made a user journey to show the current experience Pia has. Here we can see the pain-points experienced so we know areas that need focusing on.',fig('journey','User journey map','The current journey for Pia'))}
<div class="cs-hmw"><p class="cs-eye cs-rv">We chose these four HMWs as they correlate with our insights</p><h3 class="cs-h2 cs-rv">How might we…</h3><div class="cs-grow"><div class="c" style="--n:0"><span>Provide an easy onboarding process</span></div><div class="c" style="--n:1"><span>Motivate users to use Eva</span></div><div class="c" style="--n:2"><span>Personalise the experience</span></div><div class="c" style="--n:3"><span>Simplify data tracking and review</span></div></div></div>
</section>
<section class="cs-phase" style="--k:2">{phase('03','Develop','develop')}
{step('Design Studio','Using the chosen HMW’s and our problem statement we invited our client to join us in a design studio. We prioritised onboarding as the first round of the design studio, being an important part of the whole project and something we learned was needed by users when initially opening the app. In the second round we explored how we might personalise the experience for the user.',X('studio','Design studio sketches with the client'))}
{step('User Flow','We created a user flow that will show how the user will move through the app effectively.',fig('flow','User flow diagram','Three points of interest: onboarding, add features, setting reminders'))}
{step('Sketches','The three areas highlighted in the flow were what we wanted to focus on, so we timeboxed ourselves and got down to sketching.',X('sketch','Product sketches of onboarding, adding features and reminders'))}
{step('Low-Fidelity + Usability Test','We moved on from our sketches to create our low fidelity prototype on Figma. We conducted usability tests with 7 users.',''+X('lowfi','Low-fidelity prototype screens')+'<p class="cs-mini cs-rv">Test tasks</p><ol class="cs-tasks"><li style="--n:0"><i></i><span>Sign Up + Onboarding</span></li><li style="--n:1"><i></i><span>Enter Headache + Record Severity</span></li><li style="--n:2"><i></i><span>Log Paracetamol, Set Reminder + Take</span></li><li style="--n:3"><i></i><span>View Data</span></li><li style="--n:4"><i></i><span>Add New Feature</span></li></ol>')}
<div class="cs-step"><h3 class="cs-rv">What testing told us</h3><p class="cs-rv">From this we found some great insights. Here are the results:</p><dl class="cs-ba"><div class="cs-rv"><dt>Search bar</dt><dd>Users understood the function of the tool, though the size of the search bar made it hard to use.</dd></div><div class="cs-rv"><dt>Reminders</dt><dd>Changes were made to the hierarchy of information, reminders were made equal priority as medication and symptom cards and so were moved to the homepage with the bell icon.</dd></div><div class="cs-rv"><dt>Onboarding process</dt><dd>Number of screens was reduced from 10 to 6, making it less overwhelming.</dd></div><div class="cs-rv"><dt>Nav bar</dt><dd>Titles were added as well as a brief description as to the function of the plus button on the homepage.</dd></div></dl></div>
</section>
<section class="cs-phase" style="--k:3">{phase('04','Deliver','deliver')}
<div class="cs-step"><h3 class="cs-rv">High-Fidelity</h3><p class="cs-rv">Due to users liking the colours and the general UI of Alta Flora which we learned in our initial testing of the app. We decided to only change what was needed. Below you can see that the design has altered but visually it’s similar.</p>
<div class="cs-pair cs-rv"><figure><div class="ph"><img src="{I['orig']}" alt="Original EVA app home screen"></div><figcaption>Original</figcaption></figure><i aria-hidden="true">→</i><figure><div class="ph"><img src="{I['new']}" alt="New EVA app home screen"></div><figcaption>New</figcaption></figure></div></div>
{step('Custom icons + animation','While creating our prototype I asked my team member Scarlet (who is very artistic and talented at drawing) to create custom icons for our widgets to help personalise the app. As a big fan of animation and believing that interactions can really bring delight to users when going through an app I then animated these drawings using Figma.',('<div class="cs-icons cs-rv">'+''.join(f'<img src="{I[k]}" alt="Animated {n} icon" loading="lazy">' for k,n in [('ic1','sleep'),('ic2','health'),('ic3','mood'),('ic4','journal')])+'</div>') if 'ic1' in I else '')}
<div class="cs-step"><h3 class="cs-rv">High-Fidelity Testing</h3><p class="cs-rv">Nearing the end of this design sprint we wanted to test our prototype one last time before our presentation to the client. We tested the flows with 4 users.</p><div class="cs-fix"><div class="cs-rv"><blockquote>“It’s all greyed out, can I use it?”</blockquote><i aria-hidden="true">→</i><p>Coloured bar to fit symptom and made an active state for ‘Save’</p></div><div class="cs-rv"><blockquote>“The drop down button looks like a tick, not an arrow.”</blockquote><i aria-hidden="true">→</i><p>Changing it to a filled in arrow</p></div><div class="cs-rv"><blockquote>“show more needs to be made more prominent”</blockquote><i aria-hidden="true">→</i><p>Making it a more prominent button, and keeping consistency in the arrow shape.</p></div></div></div>
{step('Hitting The Brief','Our final prototype adds onboarding/coachmarks, improved UI, personalisation and further detailed information based on the input of the user. All things we learnt users needed during our research which also met the deliverables of Alta Flora.')}
</section>
<section class="cs-learn">{two('Reflection','Learnings','<p class="cs-lead">Not only was this project interesting and rewarding I learned a lot throughout it. There were some tricky parts like getting the right people to interview and being able to make them feel at ease to open up about their condition and experiences. But overcoming this we learned key insights like how users wanted a more personal experience based on their condition.</p>','learnings')}
<figure class="cs-pull cs-rv"><blockquote>“What tracking has given me is freedom and relief, so whatever tools can help identify the triggers and patterns for your symptoms - being able to look at what’s helpful and what’s not in your routine - is helpful”</blockquote><figcaption>This quote taken from one of our interviews really brought the team together seeing how much difference it can make to someone's life when they have managed pin-point the main triggers of their condition through tracking.</figcaption></figure>
<div class="cs-row cs-rv">{MED}</div></section>
{nxt('balance','Balance')}
</div></div></div>'''

balance=f'''<div class="pg cs" data-pg="balance">
<section class="cs-hero">{BAL_FX}<p class="cs-eye">Concept project · Wellbeing · 2 week sprint</p><h1 class="cs-h1">Balance</h1><p class="cs-intro">A 2 week design sprint for the meditation app Balance. In this project I worked in a team of four. Myself, Leo Wong, Alina Tamciuc, India Berrow.</p>{meta([('Role','UX Designer'),('Team','4 UX designers'),('Duration','2 weeks'),('Focus','Habit · EEG data · Group meditation')])}<div class="cs-phones one"><div class="cs-dv">{img('bhero','Three phones showcasing the Balance app designs')}</div></div></section>
<div class="cs-sheet">{rail([('Overview','overview'),('Discover','discover'),('Explore','explore'),('Develop','develop'),('Deliver','deliver'),('Summary','summary')])}
<div class="cs-wrap">
{two('The client','Who are Balance?','<p class="cs-lead">Balance is a meditation app that offers personalised meditation programs based on the meditator’s experience and needs.</p>','overview')}
{two('The brief','Brief','<p class="cs-lead">Balance believes that new meditators find meditation to be difficult and frustrating because their minds get distracted more easily during meditation, preventing them from enjoying the practice and creating a regular habit. Balance are considering partnering with Muse who make wearable brain sensing headbands, devices that measure brain activity using electroencephalography (EEG) sensors.</p><p class="cs-mini">Objectives</p><ol class="cs-obj"><li><b>01</b><span>Understand why users can’t stay engaged and what&#39;s keeping them from building a long-term meditation habit</span></li><li><b>02</b><span>Discover if using bioinformatics would increase engagement and retention</span></li><li><b>03</b><span>Explore visual solutions to help display data from EEG headbands</span></li><li><b>04</b><span>Pitch a user-validated prototype to Muse to begin conversations around collaboration opportunities</span></li></ol>')}
<section class="cs-phase" style="--k:0">{phase('01','Discover','discover')}
{step('Competitive / Comparative Analysis','To kick things off we went ahead by doing some research about the meditation app industry. We created a feature inventory to see what competitors have to offer and compared it with Balance. We learned that Balance offers most of the features apart from Social Sharing and Group Meditation.',fig('inv','Feature inventory table','Feature inventory: Calm, Headspace, Spotify, Balance, Muse','sm'))}
</section>
<section class="cs-phase" style="--k:1">{phase('02','Explore','explore')}
{step('User Interviews','We interviewed 6 users to understand the problem users are facing.',quotes(['I find meditation difficult','I like the guided sessions','I like to measure consistency with streaks','I feel tracking makes me anxious',"I'm skeptical about using bioinformatics","I can see the benefits (bioinformatics), but I'm not tempted",'I would be curious to learn more about myself (using bioinformatics)'],'Interview insights'))}
{step('Persona','Created a persona “Penny” based off insights from research and interviews.',fig('penny','Persona Penny','Meet Penny'))}
{prob('Penny wants to make meditation a habit to experience the benefits of a consistent practice, but finds it hard to commit.')}
</section>
<section class="cs-phase" style="--k:2">{phase('03','Develop','develop')}
{step('Design Studio',"We got together and did a design studio bringing our ideas to light on how we each would solve Penny's problem. Voting on our favourite ideas which we would bring forward to the next stage of the process creating the low-fidelity prototype.")}
{step('User Flow',"Making a user flow was useful to show Penny's journey through the new feature on the Balance app we are trying to create.")}
{step('Low-Fidelity and User Tests','Always so interesting moving from sketches to low-fi however due to us using the Balance app as a base we ended up being in a mid-fi instead of low-fi stage.',X('blowfi','Low-fidelity test screens for Balance'))}
</section>
<section class="cs-phase" style="--k:3">{phase('04','Deliver','deliver')}
{step('Mid-Fidelity to High-Fidelity','Due to our first design being more mid-fi we made adjustments to it based on the feedback we received and converted it to high-fi. Below are some of the screens from both paths Penny takes.',fig('hifi','High-fidelity screens','Onboarding and creating a session with a friend, then joining a live session','tall'))}
{step('Testing High-Fidelity','We tested the high-fi prototype after implementing the feedback we received from the previous tests.')}
</section>
<section class="cs-learn">{two('Reflection','Summary','<p class="cs-mini" style="margin-top:0">Moving forward</p><ul class="cs-del one"><li>More user testing</li><li>Incorporate and iterate the prototype from user feedback</li><li>Testing out more functions we proposed but we don’t have time to do at this moment, e.g. The Thought Bin, The Chat Room Function</li><li>Improve the provided information about Instructors</li></ul>','summary')}
<figure class="cs-pull cs-rv"><p class="cs-eye">Takeaway</p><blockquote>I learned so much during this 2 week sprint, mostly to test as much as possible. I feel we missed out on testing in the earlier stages and went to mid-fi too fast, something I will take forward in other sprints.</blockquote></figure>
<div class="cs-row cs-rv">{MED}</div></section>
{nxt('teach','UX Design Teaching')}
</div></div></div>'''
